import{B as e,Q as t,s as n,z as r}from"./chunks/framework.BtoUXlJN.js";var i=JSON.parse(`{"title":"Booker","description":"","frontmatter":{},"headers":[],"relativePath":"guide/booker.md","filePath":"guide/booker.md"}`),a={name:`guide/booker.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="booker" tabindex="-1">Booker <a class="header-anchor" href="#booker" aria-label="Permalink to &quot;Booker&quot;">​</a></h1><p>Welcome to the Booker guide. This documentation is automatically generated from the latest game features.</p><h2 id="show-planning-—-stipulation-required-error" tabindex="-1">Show Planning — Stipulation Required Error <a class="header-anchor" href="#show-planning-—-stipulation-required-error" aria-label="Permalink to &quot;Show Planning — Stipulation Required Error&quot;">​</a></h2><p>When a rivalry with heat ≥ 30 is on the card but has no match rule (stipulation), approval is blocked. The error dialog lists each affected rivalry. Edit the segment and add a rule such as Steel Cage or Last Man Standing before approving.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning-stipulation-error.png" alt="Show Planning — Stipulation Required Error"></p><hr><h2 id="show-planning-—-proposed-card" tabindex="-1">Show Planning — Proposed Card <a class="header-anchor" href="#show-planning-—-proposed-card" aria-label="Permalink to &quot;Show Planning — Proposed Card&quot;">​</a></h2><p>After the AI proposes segments, the booker reviews the card before approving. Rivalries with heat ≥ 10 that are not on the card will trigger an advisory when the Approve button is clicked.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning-proposed-card.png" alt="Show Planning — Proposed Card"></p><hr><h2 id="show-planning-—-unbooked-rivalries-warning" tabindex="-1">Show Planning — Unbooked Rivalries Warning <a class="header-anchor" href="#show-planning-—-unbooked-rivalries-warning" aria-label="Permalink to &quot;Show Planning — Unbooked Rivalries Warning&quot;">​</a></h2><p>When rivalries with heat ≥ 10 are not on the proposed card, a confirmation dialog lists each unbooked feud. The booker can go back and add them, or acknowledge and approve anyway — unbooked rivalries carry over to future shows.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning-must-book-warning.png" alt="Show Planning — Unbooked Rivalries Warning"></p><hr><h2 id="qr-code-match-share" tabindex="-1">QR Code Match Share <a class="header-anchor" href="#qr-code-match-share" aria-label="Permalink to &quot;QR Code Match Share&quot;">​</a></h2><p>The QR share button on a match segment opens a dialog with a scannable QR code. The URL uses the machine&#39;s LAN IP address so phones on the same network can navigate directly to the match page.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-detail-qr-code-share.png" alt="QR Code Match Share"></p><hr><h2 id="show-calendar" tabindex="-1">Show Calendar <a class="header-anchor" href="#show-calendar" aria-label="Permalink to &quot;Show Calendar&quot;">​</a></h2><p>The Show Calendar provides a monthly view of every scheduled show in the promotion. Each show appears as a colour-coded event tile on its booked date. Click any tile to jump directly to that show&#39;s detail page. Navigate between months using the prev/next arrows, or click Today to snap back to the current date.</p><p><img src="/atw-rpg/docs/screenshots/show-calendar-overview.png" alt="Show Calendar"></p><hr><h2 id="season-list" tabindex="-1">Season List <a class="header-anchor" href="#season-list" aria-label="Permalink to &quot;Season List&quot;">​</a></h2><p>Browse all seasons with their status, show count, and date range. Click &#39;Details&#39; on any season to open its full detail page, including the awards ceremony results.</p><p><img src="/atw-rpg/docs/screenshots/booker-season-list.png" alt="Season List"></p><hr><h2 id="season-detail" tabindex="-1">Season Detail <a class="header-anchor" href="#season-detail" aria-label="Permalink to &quot;Season Detail&quot;">​</a></h2><p>Full season breakdown showing key stats (status, show count, duration) and the Awards Ceremony section listing Wrestler of the Year, Most Improved, and Most Decorated winners.</p><p><img src="/atw-rpg/docs/screenshots/booker-season-detail.png" alt="Season Detail"></p><hr><h2 id="tournament-bracket-generator" tabindex="-1">Tournament Bracket Generator <a class="header-anchor" href="#tournament-bracket-generator" aria-label="Permalink to &quot;Tournament Bracket Generator&quot;">​</a></h2><p>Plan and run tournaments directly from the Booker dashboard. Choose from Single Elimination or Round Robin formats, auto-seed wrestlers by fan count or pick them manually, and book each round across your scheduled shows.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-list.png" alt="Tournament Bracket Generator"></p><hr><h2 id="tournament-detail-—-scheduled" tabindex="-1">Tournament Detail — Scheduled <a class="header-anchor" href="#tournament-detail-—-scheduled" aria-label="Permalink to &quot;Tournament Detail — Scheduled&quot;">​</a></h2><p>A freshly created tournament shows all entrants seeded and ready. The &#39;Start Tournament&#39; button generates the first-round bracket. Entrants are ranked by seed — 1 vs 8, 2 vs 7, and so on.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-detail-scheduled.png" alt="Tournament Detail — Scheduled"></p><hr><h2 id="tournament-detail-—-in-progress" tabindex="-1">Tournament Detail — In Progress <a class="header-anchor" href="#tournament-detail-—-in-progress" aria-label="Permalink to &quot;Tournament Detail — In Progress&quot;">​</a></h2><p>Live tournament view shows completed round results and the pending next round. The booker can book the upcoming round onto any scheduled show and record match winners as each event is completed.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-detail-in-progress.png" alt="Tournament Detail — In Progress"></p><hr><h2 id="dashboard-with-news-ticker" tabindex="-1">Dashboard with News Ticker <a class="header-anchor" href="#dashboard-with-news-ticker" aria-label="Permalink to &quot;Dashboard with News Ticker&quot;">​</a></h2><p>Latest headlines and rumors are visible directly on the booker dashboard.</p><p><img src="/atw-rpg/docs/screenshots/booker-dashboard-news-ticker.png" alt="Dashboard with News Ticker"></p><hr><h2 id="show-planning" tabindex="-1">Show Planning <a class="header-anchor" href="#show-planning" aria-label="Permalink to &quot;Show Planning&quot;">​</a></h2><p>The Show Planning interface allows you to book matches and segments for an upcoming show. Drag and drop wrestlers to create matches, set stipulations, and define segment types.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning.png" alt="Show Planning"></p><hr><h2 id="match-narration" tabindex="-1">Match Narration <a class="header-anchor" href="#match-narration" aria-label="Permalink to &quot;Match Narration&quot;">​</a></h2><p>Bring your matches to life with AI-generated or manual narration. The Story Director uses match participants, rules, and outcomes to weave a compelling narrative of the action. The new structured transcript format separates objective action from character-driven commentary.</p><p><img src="/atw-rpg/docs/screenshots/booker-match-narration.png" alt="Match Narration"></p><hr><h2 id="show-history" tabindex="-1">Show History <a class="header-anchor" href="#show-history" aria-label="Permalink to &quot;Show History&quot;">​</a></h2><p>View a complete history of all booked shows. Click on any show to view its detailed results, ratings, and match history.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-history.png" alt="Show History"></p><hr><h2 id="video-walkthroughs" tabindex="-1">Video Walkthroughs <a class="header-anchor" href="#video-walkthroughs" aria-label="Permalink to &quot;Video Walkthroughs&quot;">​</a></h2><h3 id="show-card-validation-walkthrough" tabindex="-1">Show Card Validation Walkthrough <a class="header-anchor" href="#show-card-validation-walkthrough" aria-label="Permalink to &quot;Show Card Validation Walkthrough&quot;">​</a></h3><p>After the booker confirms, the segments are saved to the show. Each approved segment enters the adjudication pipeline — the match engine resolves outcomes, updates wrestler stats, and the AI generates narration ready for broadcast.</p><video controls width="100%" style="border-radius:8px;margin-bottom:1rem;"><source src="https://javydreamercsw.github.io/all-time-wrestling-rpg/videos/booker-show-planning-card-validation-walkthrough.mp4" type="video/mp4"></video><hr><h3 id="show-calendar-walkthrough" tabindex="-1">Show Calendar Walkthrough <a class="header-anchor" href="#show-calendar-walkthrough" aria-label="Permalink to &quot;Show Calendar Walkthrough&quot;">​</a></h3><p>Shows scheduled in future months appear here as soon as they&#39;re created in the Show List. Plan your entire PPV season at a glance — weekly shows, special events, and pay-per-view dates all land on the same calendar.</p><video controls width="100%" style="border-radius:8px;margin-bottom:1rem;"><source src="https://javydreamercsw.github.io/all-time-wrestling-rpg/videos/show-calendar-walkthrough.mp4" type="video/mp4"></video><hr><h3 id="season-awards-ceremony" tabindex="-1">Season Awards Ceremony <a class="header-anchor" href="#season-awards-ceremony" aria-label="Permalink to &quot;Season Awards Ceremony&quot;">​</a></h3><p>The Awards Ceremony section lists each award winner: Wrestler of the Year (most wins), Most Improved (highest fan growth), and Most Decorated (most title reigns). Winners automatically receive fan bonuses when the season ends.</p><video controls width="100%" style="border-radius:8px;margin-bottom:1rem;"><source src="https://javydreamercsw.github.io/all-time-wrestling-rpg/videos/booker-season-awards-workflow.mp4" type="video/mp4"></video><hr><h3 id="tournament-bracket-generator-1" tabindex="-1">Tournament Bracket Generator <a class="header-anchor" href="#tournament-bracket-generator-1" aria-label="Permalink to &quot;Tournament Bracket Generator&quot;">​</a></h3><p>The tournament engine supports Single Elimination and Round Robin formats. Single Elimination generates one round at a time, perfect for big multi-week events. Round Robin pre-builds all match-ups so every entrant faces every other entrant before a winner is determined.</p><video controls width="100%" style="border-radius:8px;margin-bottom:1rem;"><source src="https://javydreamercsw.github.io/all-time-wrestling-rpg/videos/booker-tournament-bracket-workflow.mp4" type="video/mp4"></video><hr>`,75)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};